(function(root){
  'use strict';
  const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const verdicts={correct:'Fachpunkte erfüllt',partial:'Teilweise erklärt',incorrect:'Fachliche Korrektur nötig',unclear:'Nicht sicher beurteilbar'};
  const statuses={approved:'Richtig erklärt',missing:'Noch ergänzen',incorrect:'Bitte korrigieren',unclear:'Unklar'};
  function feedback(result){return `<section class="ai-feedback ${escape(result.verdict)}" aria-label="${(result.manualVisual||result.manualSelf)?'Eigener Vergleich':'KI-Rückmeldung'}"><div class="eyebrow">${(result.manualVisual||result.manualSelf)?'DEIN EIGENER VERGLEICH · DEINE SELBSTEINSCHÄTZUNG':result.unanswered?'LEER ABGEGEBENE ANTWORT':'GEMINI · RÜCKMELDUNG ZU DEINER ERKLÄRUNG'}</div><h2>${verdicts[result.verdict]||verdicts.unclear}</h2><p>${escape(result.summary)}</p><div class="feedback-points">${result.points.map(p=>`<div class="feedback-point ${escape(p.status)}"><span class="feedback-status">${statuses[p.status]||statuses.unclear}</span><h3>${escape(p.label)}</h3><p>${escape(p.feedback)}</p></div>`).join('')}</div><div class="next-step"><strong>Dein nächster Schritt</strong><p>${escape(result.nextStep)}</p></div><small>${(result.manualVisual||result.manualSelf)?'Eigener Vergleich mit der Vorlage. Keine KI-Bewertung.':result.unanswered?'Keine KI-Anfrage: Hier wurde keine Antwort abgegeben.':'KI-Lernfeedback · kann Fehler enthalten · keine offizielle Prüfungsnote'}</small></section>`;}
  function render({card,current,session,icon,button,drawings='',reference='',ai}){
    const visual=root.LernpassWorkbook?root.LernpassWorkbook.isVisual(card):Boolean(card.imagePage);const text=session.scratch||'',progress=Math.round(session.position/session.ids.length*100),ready=text.trim().length>=5;
    return `<div class="session-top">${button('end-session',icon('back')+' Training beenden','link-button')}<span>FREI ANTWORTEN</span><b>In deinen eigenen Worten</b></div><div class="session-track"><i style="width:${progress}%"></i></div><div class="session-counter">Fall ${session.position+1} von ${session.ids.length}<span> · Stufe ${current.stage} von 5</span></div><article class="study-card panel free-study"><div class="card-labels"><span class="case-id">${card.id}</span><span class="tag">${escape(card.category)}</span><span class="writing-tag">${icon('learn')} FREITEXT</span></div><h1>${escape(card.title)}</h1><p class="study-question">${escape(card.question)}</p><div class="recall-box">${icon('spark')}<span>Erkläre den Zusammenhang so, wie du ihn verstanden hast. Es gibt keine Antwortauswahl. Die Fachpunkte bleiben verborgen, bis du sie öffnen möchtest.</span></div>${visual?(root.LernpassWorkbook?.visualNote(card)||''):''}${drawings?`<div class="recall-drawing">${drawings}</div>`:''}${session.submitted?`<section class="own-explanation"><div class="section-top"><h2>Deine Erklärung</h2>${button('edit-answer','Überarbeiten','text-link',session.checking?'disabled':'')}</div><p class="answer-verbatim">${escape(text)}</p><span class="saved-answer">${icon('check')} Auf diesem Gerät gespeichert</span></section>`:`<label class="field-label" for="scratchAnswer">Deine eigene Erklärung <span>Entwurf wird automatisch auf diesem Gerät gespeichert</span></label><textarea id="scratchAnswer" class="free-answer-input" maxlength="6000" rows="9" aria-describedby="freeAnswerCount" placeholder="Erkläre es in deinen Worten. Du kannst auch ein Beispiel aus deinem Betrieb nennen …">${escape(text)}</textarea><div class="writing-footer"><span id="freeAnswerCount">${text.length} / 6.000 Zeichen</span><span>Stichpunkte sind genauso möglich.</span></div>`}<div class="free-actions button-row">${visual?'':!ai.configured?button('ai-settings','KI optional verbinden','button secondary'):session.checking?`<button class="button primary" disabled><span class="loading-dot"></span> Gemini prüft deine Erklärung …</button>`:button('check-answer',icon('spark')+(session.assessment?'Erneut mit Gemini prüfen':'Mit Gemini prüfen'),'button primary',ready?'':'disabled')}${!session.submitted?button('submit-answer','Antwort speichern','button secondary',ready?'':'disabled'):''}${session.submitted&&!session.revealed?button('reveal',icon('eye')+' Fachpunkte vergleichen','button secondary'):''}</div><p class="ai-disclosure">${visual?'Bild- und Skizzenfragen werden nur mit der Vorlage selbst verglichen. Es werden keine Bilder oder Antworten dieser Frage an Gemini gesendet.':ai.configured?'Beim Prüfen werden nur diese Antwort, die Frage und ihre Fachpunkte an Google Gemini gesendet. Dein Entwurf bleibt bis dahin lokal.':'Gemini-Anbindung vorbereitet · Der API-Zugang muss noch eingerichtet werden. Du kannst deine Erklärung schon speichern und die Fachpunkte selbst vergleichen.'}</p>${session.checkError?`<div class="notice warning" role="alert">${escape(session.checkError)}</div>`:''}${session.assessment?feedback(session.assessment):''}${session.revealed?reference:''}</article>${session.submitted&&!session.checking?`<section class="rating-panel" aria-label="Antwort einschätzen"><div><h2>Was nimmst du aus deiner Antwort mit?</h2><p>${session.assessment?'Nutze die Rückmeldung für deine eigene Einschätzung.':'Du schätzt deinen Wissensstand selbst ein. Der Text wurde noch nicht durch die KI bewertet.'}</p></div><div class="rating-buttons">${button('grade','<b>Nochmal</b><small>heute wiederholen</small>','rating again','data-grade="again"')}${button('grade','<b>Unsicher</b><small>früher festigen</small>','rating hard','data-grade="hard"')}${button('grade','<b>Gewusst</b><small>Abstand vergrößern</small>','rating good','data-grade="good"')}</div></section>`:''}`;
  }
  const api={render,feedback};root.LernpassWriter=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
